<script setup>import{useForm,router}from'@inertiajs/vue3';import AdminLayout from'../../Layouts/AdminLayout.vue';const props=defineProps({productCategories:Array,serviceCategories:Array,brands:Array,view:String,counts:Object});const category=useForm({name:'',slug:'',type:'product',description:'',image:null,image_url:'',is_active:true,sort_order:0}),brand=useForm({name:'',slug:'',is_active:true});const addCategory=()=>category.post('/admin/catalog/categories',{forceFormData:true,onSuccess:()=>category.reset()}),addBrand=()=>brand.post('/admin/catalog/brands',{onSuccess:()=>brand.reset()});const del=(type,id)=>confirm('Move to Trash?')&&router.delete(`/admin/catalog/${type}/${id}`);</script><template><AdminLayout><p class="section-kicker">Catalogue</p><h1 class="section-title">Categories & brands</h1><div class="mt-6 grid gap-5 lg:grid-cols-2"><form class="card p-5" @submit.prevent="addCategory"><h2 class="font-black">Add category</h2><div class="mt-4 grid gap-3"><input v-model="category.name" class="input" placeholder="Category name"><select v-model="category.type" class="input"><option value="product">Product category</option><option value="service">Service category</option></select><textarea v-model="category.description" class="input" placeholder="Description"></textarea><input type="file" @change="category.image=$event.target.files[0]"><button class="btn-primary">Save category</button></div></form><form class="card p-5" @submit.prevent="addBrand"><h2 class="font-black">Add brand</h2><div class="mt-4 grid gap-3"><input v-model="brand.name" class="input" placeholder="Brand name"><button class="btn-primary">Save brand</button></div></form></div><div class="mt-6 grid gap-5 lg:grid-cols-3"><section class="card p-5"><h2 class="font-black">Product categories</h2><div class="mt-3 divide-y"><div v-for="c in productCategories" :key="c.id" class="flex justify-between py-3 text-sm"><span><b>{{c.name}}</b><br><span class="text-slate-500">{{c.products_count}} products</span></span><button class="font-bold text-red-600" @click="del('categories',c.id)">Trash</button></div></div></section><section class="card p-5"><h2 class="font-black">Service categories</h2><div class="mt-3 divide-y"><div v-for="c in serviceCategories" :key="c.id" class="flex justify-between py-3 text-sm"><span><b>{{c.name}}</b><br><span class="text-slate-500">{{c.services_count}} services</span></span><button class="font-bold text-red-600" @click="del('categories',c.id)">Trash</button></div></div></section><section class="card p-5"><h2 class="font-black">Brands</h2><div class="mt-3 divide-y"><div v-for="b in brands" :key="b.id" class="flex justify-between py-3 text-sm"><span><b>{{b.name}}</b><br><span class="text-slate-500">{{b.products_count}} products</span></span><button class="font-bold text-red-600" @click="del('brands',b.id)">Trash</button></div></div></section></div></AdminLayout></template>
